// ============================================================================
// ipcam_soc_mm_engine_regs -- APB4 register file generated by socgen from
// register_blocks.mm_engine in socgen/specs/ipcam_soc.yaml. Media engine control (frame descriptors, start/status, QoS)
//  - zero wait states, 32-bit data, 12-bit byte address, PSTRB byte lanes
//  - PSLVERR on an unmapped or misaligned offset
//  - hw_* inputs: values of RO registers and set pulses of W1C bits (from the
//    block's logic; tie to 0 for a register-only model)
// ============================================================================
module ipcam_soc_mm_engine_regs (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  input  logic [31:0] hw_status,
  input  logic [31:0] hw_irq_status,
  output logic [31:0] q_ctrl,
  output logic [31:0] q_start,
  output logic [31:0] q_src_addr,
  output logic [31:0] q_dst_addr,
  output logic [31:0] q_stride,
  output logic [31:0] q_frame_size,
  output logic [31:0] q_qos,
  output logic        we_start
);
  wire        acc   = PSEL & PENABLE;
  wire        wr    = acc & PWRITE;
  wire [31:0] wmask = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic       hit;
  always_comb begin
    hit = 1'b0;
    case (PADDR)
      12'h000: hit = 1'b1;
      12'h004: hit = 1'b1;
      12'h008: hit = 1'b1;
      12'h00C: hit = 1'b1;
      12'h010: hit = 1'b1;
      12'h014: hit = 1'b1;
      12'h018: hit = 1'b1;
      12'h01C: hit = 1'b1;
      12'h020: hit = 1'b1;
      12'h024: hit = 1'b1;
      default: hit = 1'b0;
    endcase
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~hit;

  // 000 ID RO reset 0x4D450100: code 0x4D45 ('ME'), version 1.0
  // 004 CTRL RW reset 0x00000000
  logic [31:0] r_ctrl;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_ctrl <= 32'h00000000;
    else if (wr && PADDR == 12'h004)
      r_ctrl <= ((r_ctrl & ~wmask) | (PWDATA & wmask)) & 32'h000000F3;
  assign q_ctrl = r_ctrl;
  // 008 START WO reset 0x00000000: write 1 to start a frame
  logic [31:0] r_start;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_start <= 32'h00000000;
    else if (wr && PADDR == 12'h008)
      r_start <= ((r_start & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_start = r_start;
  assign we_start = wr && PADDR == 12'h008;
  // 00C STATUS RO reset 0x00000000
  // 010 SRC_ADDR RW reset 0x00000000
  logic [31:0] r_src_addr;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_src_addr <= 32'h00000000;
    else if (wr && PADDR == 12'h010)
      r_src_addr <= ((r_src_addr & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_src_addr = r_src_addr;
  // 014 DST_ADDR RW reset 0x00000000
  logic [31:0] r_dst_addr;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_dst_addr <= 32'h00000000;
    else if (wr && PADDR == 12'h014)
      r_dst_addr <= ((r_dst_addr & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_dst_addr = r_dst_addr;
  // 018 STRIDE RW reset 0x00000000
  logic [31:0] r_stride;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_stride <= 32'h00000000;
    else if (wr && PADDR == 12'h018)
      r_stride <= ((r_stride & ~wmask) | (PWDATA & wmask)) & 32'h0000FFFF;
  assign q_stride = r_stride;
  // 01C FRAME_SIZE RW reset 0x00000000
  logic [31:0] r_frame_size;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_frame_size <= 32'h00000000;
    else if (wr && PADDR == 12'h01C)
      r_frame_size <= ((r_frame_size & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_frame_size = r_frame_size;
  // 020 QOS RW reset 0x00000000
  logic [31:0] r_qos;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_qos <= 32'h00000000;
    else if (wr && PADDR == 12'h020)
      r_qos <= ((r_qos & ~wmask) | (PWDATA & wmask)) & 32'h00000F0F;
  assign q_qos = r_qos;
  // 024 IRQ_STATUS W1C reset 0x00000000
  logic [31:0] r_irq_status;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_irq_status <= 32'h00000000;
    else r_irq_status <= ((r_irq_status & ~((wr && PADDR == 12'h024) ? (PWDATA & wmask) : 32'h0))
                         | hw_irq_status) & 32'h00000003;

  always_comb begin
    PRDATA = 32'h0;
    if (acc && !PWRITE)
      case (PADDR)
        12'h000: PRDATA = 32'h4D450100;
        12'h004: PRDATA = r_ctrl;
        12'h008: PRDATA = 32'h0;
        12'h00C: PRDATA = hw_status & 32'h00000007;
        12'h010: PRDATA = r_src_addr;
        12'h014: PRDATA = r_dst_addr;
        12'h018: PRDATA = r_stride;
        12'h01C: PRDATA = r_frame_size;
        12'h020: PRDATA = r_qos;
        12'h024: PRDATA = r_irq_status;
        default: PRDATA = 32'h0;
      endcase
  end
endmodule
